// Generated by scripts/build-startup-templates.js. Edit the source HTML templates.
export const startupTemplates = {
    '/scripts/templates/wandButton.html': '<div id="extensionsMenuButton" style="display: none;" class="fa-solid fa-magic-wand-sparkles interactable" title="Extensions" data-i18n="[title]Extensions"></div>\n',
    '/scripts/templates/wandMenu.html': '<div id="extensionsMenu" class="options-content" style="display: none;">\n    <div id="wand_message_screenshot" class="list-group-item flex-container flexGap5" title="Screenshot message(s)" data-i18n="[title]Screenshot message(s)">\n        <div class="fa-solid fa-camera extensionsMenuExtensionButton"></div>\n        <span data-i18n="Screenshot message(s)">Screenshot message(s)</span>\n    </div>\n    <div id="wand_group_speaker_controls" class="list-group-item flex-container flexGap5" title="Show the group bar" data-i18n="[title]Show the group bar">\n        <div class="fa-solid fa-eye extensionsMenuExtensionButton"></div>\n        <span data-i18n="Show Group Bar">Show Group Bar</span>\n    </div>\n    <div id="data_bank_wand_container" class="extension_container"></div>\n    <div id="attach_file_wand_container" class="extension_container"></div>\n    <div id="sd_wand_container" class="extension_container"></div>\n    <div id="caption_wand_container" class="extension_container"></div>\n    <div id="gallery_wand_container" class="extension_container"></div>\n    <div id="tts_wand_container" class="extension_container"></div>\n    <div id="screen_share_wand_container" class="extension_container"></div>\n    <div id="prompt_inspector_wand_container" class="extension_container"></div>\n    <div id="emulatorjs_wand_container" class="extension_container"></div>\n    <div id="notebook_wand_container" class="extension_container"></div>\n    <div id="chess_wand_container" class="extension_container"></div>\n    <div id="token_counter_wand_container" class="extension_container"></div>\n    <div id="dice_wand_container" class="extension_container"></div>\n    <div id="objective_wand_container" class="extension_container"></div>\n    <div id="translate_wand_container" class="extension_container"></div>\n</div>\n',
    '/scripts/templates/help.html': '<div class="necoHelp">\n    <header class="necoHelpHero">\n        <div class="necoHelpCast" aria-hidden="true">\n            <img class="necoHelpFace necoHelpFace--miso" src="img/neconyan/assistant-icons/miso-neutral.png?v=20260916-art4" alt="">\n            <img class="necoHelpFace necoHelpFace--taro" src="img/neconyan/assistant-icons/taro-neutral.png?v=20260916-art4" alt="">\n            <img class="necoHelpFace necoHelpFace--nori" src="img/neconyan/assistant-icons/nori-neutral.png?v=20260916-art4" alt="">\n        </div>\n        <div class="necoHelpHeroText">\n            <h3 class="necoHelpTitle">Neconyan help</h3>\n            <p class="necoHelpLead">Miso, Taro and Nori have split this guide between them. Open whichever section matches what you\'re stuck on, or jump straight to a full list.</p>\n            <p>For screenshot guides and the full macro reference, read the <a href="https://platberlitz.github.io/neconyan-docs/" target="_blank" rel="noopener noreferrer">official Neconyan handbook</a>.</p>\n        </div>\n    </header>\n\n    <div class="necoHelpJump" role="group" aria-label="Full lists">\n        <button type="button" class="necoHelpChip" data-displayHelp="1"><i class="fa-solid fa-terminal" aria-hidden="true"></i><span>Slash commands</span></button>\n        <button type="button" class="necoHelpChip" data-displayHelp="4"><i class="fa-solid fa-code" aria-hidden="true"></i><span>Macro list</span></button>\n        <button type="button" class="necoHelpChip" data-displayHelp="2"><i class="fa-solid fa-font" aria-hidden="true"></i><span>Formatting</span></button>\n        <button type="button" class="necoHelpChip" data-displayHelp="3"><i class="fa-solid fa-keyboard" aria-hidden="true"></i><span>Hotkeys</span></button>\n    </div>\n\n    <details class="necoHelpHost necoHelpHost--miso">\n        <summary class="necoHelpHostHead">\n            <img class="necoHelpFace necoHelpFace--miso" src="img/neconyan/assistant-icons/miso-neutral.png?v=20260916-art4" alt="">\n            <span class="necoHelpHostText">\n                <span class="necoHelpHostName">Miso</span>\n                <span class="necoHelpHostTopic">Getting around: commands, formatting and shortcuts</span>\n            </span>\n        </summary>\n        <div class="necoHelpBody">\n            <p class="necoHelpSays">Meowlcome~! I\'ll show you the quick stuff first, so you can do things without digging through menus. And if this helps, a belly rub would be lovely. Just saying, hehe.</p>\n\n            <h4 class="necoHelpHeading">Slash commands</h4>\n            <p>A slash command is an instruction you type into the chat box instead of a message. Type <code>/</code> and a list of matching commands pops up, each with a short description. Press Enter to run the one you want.</p>\n            <dl class="necoHelpList">\n                <dt><code>/?</code></dt>\n                <dd>Opens this guide. Add <code>slash</code>, <code>macros</code>, <code>format</code> or <code>hotkeys</code> for a full list, like <code>/? macros</code>.</dd>\n                <dt><code>/sys The rain stops.</code></dt>\n                <dd>Posts a narrator message into the chat without asking the model to reply.</dd>\n                <dt><code>/continue</code></dt>\n                <dd>Asks the model to keep writing its last reply.</dd>\n                <dt><code>/hide 4</code></dt>\n                <dd>Hides message number 4 from the model. You can still see it, and <code>/unhide 4</code> brings it back.</dd>\n                <dt><code>/gen A one-line café description</code></dt>\n                <dd>Asks the model for text and hands it to the next command instead of posting it.</dd>\n                <dt><code>/echo Hello!</code></dt>\n                <dd>Shows a small pop-up notice.</dd>\n            </dl>\n            <p class="necoHelpTip">Put <code>|</code> between commands to run them one after another. Each command\'s result reaches the next one as <code>&lcub;&lcub;pipe&rcub;&rcub;</code>, so <code>/gen A one-line café description | /echo &lcub;&lcub;pipe&rcub;&rcub;</code> shows the model\'s answer in a pop-up.</p>\n\n            <h4 class="necoHelpHeading">Making text look nice</h4>\n            <p>Messages understand Markdown, which styles text with a few symbols around it.</p>\n            <div class="necoHelpSamples">\n                <span class="necoHelpSample"><code>*italics*</code><em>italics</em></span>\n                <span class="necoHelpSample"><code>**bold**</code><strong>bold</strong></span>\n                <span class="necoHelpSample"><code>__underline__</code><u>underline</u></span>\n                <span class="necoHelpSample"><code>~~strike~~</code><del>strike</del></span>\n                <span class="necoHelpSample"><code>`code`</code><code>code</code></span>\n                <span class="necoHelpSample"><code>&gt; quote</code><span>quote block</span></span>\n            </div>\n\n            <h4 class="necoHelpHeading">Handy shortcuts</h4>\n            <dl class="necoHelpList necoHelpList--keys">\n                <dt><kbd>Enter</kbd></dt>\n                <dd>Send your message.</dd>\n                <dt><kbd>Ctrl</kbd> <kbd>Enter</kbd></dt>\n                <dd>Regenerate the last reply.</dd>\n                <dt><kbd>Alt</kbd> <kbd>Enter</kbd></dt>\n                <dd>Continue the last reply.</dd>\n                <dt><kbd>←</kbd> <kbd>→</kbd></dt>\n                <dd>Swipe between alternative replies while the chat box is empty.</dd>\n                <dt><kbd>↑</kbd></dt>\n                <dd>Edit your last message.</dd>\n                <dt><kbd>Esc</kbd></dt>\n                <dd>Stop a reply that\'s being written, or cancel an edit.</dd>\n            </dl>\n            <div class="necoHelpActions">\n                <button type="button" class="necoHelpChip" data-displayHelp="1"><span>All slash commands</span></button>\n                <button type="button" class="necoHelpChip" data-displayHelp="2"><span>All formatting</span></button>\n                <button type="button" class="necoHelpChip" data-displayHelp="3"><span>All hotkeys</span></button>\n            </div>\n        </div>\n    </details>\n\n    <details class="necoHelpHost necoHelpHost--taro">\n        <summary class="necoHelpHostHead">\n            <img class="necoHelpFace necoHelpFace--taro" src="img/neconyan/assistant-icons/taro-neutral.png?v=20260916-art4" alt="">\n            <span class="necoHelpHostText">\n                <span class="necoHelpHostName">Taro</span>\n                <span class="necoHelpHostTopic">Macros: placeholders that fill themselves in</span>\n            </span>\n        </summary>\n        <div class="necoHelpBody">\n            <p class="necoHelpSays">Taro. Give me a second, my voice is a little rough today. A macro is a word in double curly brackets, and right before anything goes to the model, Neconyan swaps it for the real value. Write it once, and it stays right no matter who you\'re talking to. That\'s a purr-fectly good deal. Tell me that was funny.</p>\n\n            <h4 class="necoHelpHeading">Where they work</h4>\n            <p>Character cards, presets and prompts, lorebook entries and slash commands. Write <code>&lcub;&lcub;char&rcub;&rcub;</code> in a prompt and it becomes the name of whichever character you\'re chatting with.</p>\n\n            <h4 class="necoHelpHeading">Names and the character card</h4>\n            <dl class="necoHelpList">\n                <dt><code>&lcub;&lcub;user&rcub;&rcub;</code></dt>\n                <dd>Your persona\'s name.</dd>\n                <dt><code>&lcub;&lcub;char&rcub;&rcub;</code></dt>\n                <dd>The character\'s name.</dd>\n                <dt><code>&lcub;&lcub;group&rcub;&rcub;</code></dt>\n                <dd>Everyone in a group chat, separated by commas. In a one-to-one chat it\'s just the character.</dd>\n                <dt><code>&lcub;&lcub;persona&rcub;&rcub;</code></dt>\n                <dd>Your persona\'s description.</dd>\n                <dt><code>&lcub;&lcub;description&rcub;&rcub;</code> <code>&lcub;&lcub;personality&rcub;&rcub;</code> <code>&lcub;&lcub;scenario&rcub;&rcub;</code></dt>\n                <dd>Those fields from the character card.</dd>\n                <dt><code>&lcub;&lcub;model&rcub;&rcub;</code></dt>\n                <dd>The name of the model you\'re connected to.</dd>\n            </dl>\n\n            <h4 class="necoHelpHeading">The chat so far</h4>\n            <dl class="necoHelpList">\n                <dt><code>&lcub;&lcub;lastMessage&rcub;&rcub;</code></dt>\n                <dd>The newest message in the chat.</dd>\n                <dt><code>&lcub;&lcub;lastUserMessage&rcub;&rcub;</code> <code>&lcub;&lcub;lastCharMessage&rcub;&rcub;</code></dt>\n                <dd>Your newest message, or the character\'s.</dd>\n                <dt><code>&lcub;&lcub;input&rcub;&rcub;</code></dt>\n                <dd>Whatever is typed in the chat box right now.</dd>\n            </dl>\n\n            <h4 class="necoHelpHeading">Time</h4>\n            <dl class="necoHelpList">\n                <dt><code>&lcub;&lcub;time&rcub;&rcub;</code> <code>&lcub;&lcub;date&rcub;&rcub;</code> <code>&lcub;&lcub;weekday&rcub;&rcub;</code></dt>\n                <dd>The current time, date and day of the week. <code>&lcub;&lcub;time::UTC+2&rcub;&rcub;</code> uses another time zone.</dd>\n                <dt><code>&lcub;&lcub;idleDuration&rcub;&rcub;</code></dt>\n                <dd>How long it\'s been since your last message.</dd>\n            </dl>\n\n            <h4 class="necoHelpHeading">Random picks and dice</h4>\n            <dl class="necoHelpList">\n                <dt><code>&lcub;&lcub;random::tea::coffee::cocoa&rcub;&rcub;</code></dt>\n                <dd>Picks one option, and picks again every time.</dd>\n                <dt><code>&lcub;&lcub;pick::tea::coffee::cocoa&rcub;&rcub;</code></dt>\n                <dd>Picks once and keeps that answer for this chat. <code>/reroll-pick</code> picks again.</dd>\n                <dt><code>&lcub;&lcub;roll::1d20&rcub;&rcub;</code></dt>\n                <dd>Rolls dice, here one twenty-sided die.</dd>\n            </dl>\n\n            <h4 class="necoHelpHeading">Variables</h4>\n            <p>A variable is a named value that Neconyan remembers for you. Local variables belong to the current chat; global variables are shared by every chat.</p>\n            <dl class="necoHelpList">\n                <dt><code>&lcub;&lcub;setvar::hp::20&rcub;&rcub;</code></dt>\n                <dd>Saves 20 under the name hp. It leaves no text behind.</dd>\n                <dt><code>&lcub;&lcub;getvar::hp&rcub;&rcub;</code> or <code>&lcub;&lcub;.hp&rcub;&rcub;</code></dt>\n                <dd>Reads it back.</dd>\n                <dt><code>&lcub;&lcub;addvar::hp::5&rcub;&rcub;</code> <code>&lcub;&lcub;incvar::turns&rcub;&rcub;</code></dt>\n                <dd>Adds 5 to hp, or adds 1 to turns.</dd>\n                <dt><code>&lcub;&lcub;.hp -= 5&rcub;&rcub;</code> <code>&lcub;&lcub;.turns++&rcub;&rcub;</code></dt>\n                <dd>The short way to change a local variable.</dd>\n                <dt><code>&lcub;&lcub;setglobalvar::gold::100&rcub;&rcub;</code> or <code>&lcub;&lcub;$gold&rcub;&rcub;</code></dt>\n                <dd>The same idea for global variables.</dd>\n            </dl>\n\n            <h4 class="necoHelpHeading">Conditions and tidying</h4>\n            <dl class="necoHelpList">\n                <dt><code>&lcub;&lcub;if .hp&rcub;&rcub;Still standing.&lcub;&lcub;else&rcub;&rcub;Down!&lcub;&lcub;/if&rcub;&rcub;</code></dt>\n                <dd>Shows the first part when the condition has a value, otherwise the part after else. Empty, false, off and 0 count as no. Put <code>!</code> in front to flip it.</dd>\n                <dt><code>&lcub;&lcub;// a note to yourself&rcub;&rcub;</code></dt>\n                <dd>A comment. It disappears before the model sees anything.</dd>\n                <dt><code>&lcub;&lcub;newline&rcub;&rcub;</code> <code>&lcub;&lcub;trim&rcub;&rcub;</code></dt>\n                <dd>Adds a line break, or removes the blank lines around it.</dd>\n            </dl>\n            <p class="necoHelpTip">Arguments go after the macro\'s name, separated by <code>::</code>. You can put macros inside macros; the inner one is worked out first.</p>\n            <div class="necoHelpActions">\n                <button type="button" class="necoHelpChip" data-displayHelp="4"><span>Every macro, searchable</span></button>\n            </div>\n        </div>\n    </details>\n\n    <details class="necoHelpHost necoHelpHost--nori">\n        <summary class="necoHelpHostHead">\n            <img class="necoHelpFace necoHelpFace--nori" src="img/neconyan/assistant-icons/nori-neutral.png?v=20260916-art4" alt="">\n            <span class="necoHelpHostText">\n                <span class="necoHelpHostName">Nori</span>\n                <span class="necoHelpHostTopic">Macro Enhanced: cheaper prompts and fancier macros</span>\n            </span>\n        </summary>\n        <div class="necoHelpBody">\n            <p class="necoHelpSays">Nori here. Macro Enhanced is the extension that comes with Neconyan and teaches macros some manners. I invented it, obviously. ...Fine, I didn\'t. But it saves you money, and I have very expensive taste and a very empty wallet, so listen closely.</p>\n\n            <h4 class="necoHelpHeading">Why it saves money</h4>\n            <p>Some providers keep the unchanged start of your prompt ready between messages, which is called prompt caching. It makes replies cheaper and faster, but only while that start stays exactly the same. A macro that changes every message, like <code>&lcub;&lcub;time&rcub;&rcub;</code> or <code>&lcub;&lcub;random&rcub;&rcub;</code>, spoils it every time. Swap them for these:</p>\n            <dl class="necoHelpList necoHelpList--swap">\n                <dt><code>&lcub;&lcub;timeofday&rcub;&rcub;</code></dt>\n                <dd>Morning, afternoon, evening or night, instead of <code>&lcub;&lcub;time&rcub;&rcub;</code>.</dd>\n                <dt><code>&lcub;&lcub;season&rcub;&rcub;</code></dt>\n                <dd>The season instead of <code>&lcub;&lcub;date&rcub;&rcub;</code>. <code>&lcub;&lcub;season::south&rcub;&rcub;</code> for the southern hemisphere.</dd>\n                <dt><code>&lcub;&lcub;listpick::drink::tea, coffee, cocoa&rcub;&rcub;</code></dt>\n                <dd>The same pick every time in this chat, instead of <code>&lcub;&lcub;random&rcub;&rcub;</code>.</dd>\n                <dt><code>&lcub;&lcub;rollonce::strength::3d6&rcub;&rcub;</code></dt>\n                <dd>Rolls once and keeps the total, instead of <code>&lcub;&lcub;roll&rcub;&rcub;</code>.</dd>\n                <dt><code>&lcub;&lcub;freeze::weather::&lcub;&lcub;random::stormy::misty::clear&rcub;&rcub;&rcub;&rcub;</code></dt>\n                <dd>Works out whatever is inside once and keeps it for the rest of this chat.</dd>\n                <dt><code>&lcub;&lcub;sticky::10::mood::&lcub;&lcub;random::tense::playful&rcub;&rcub;&rcub;&rcub;</code></dt>\n                <dd>Same idea, but refreshes after every 10 of your messages. <code>&lcub;&lcub;daily::key::...&rcub;&rcub;</code> refreshes once a day.</dd>\n            </dl>\n            <p class="necoHelpTip"><code>/me-audit</code> finds macros in your presets, character, persona and lorebooks that spoil caching. <code>/me-unfreeze</code> clears kept values so they roll again.</p>\n\n            <h4 class="necoHelpHeading">Comparisons and maths</h4>\n            <dl class="necoHelpList">\n                <dt><code>&lcub;&lcub;gt::&lcub;&lcub;getvar::hp&rcub;&rcub;::10&rcub;&rcub;</code></dt>\n                <dd>Says true when hp is above 10. Also <code>eq</code>, <code>neq</code>, <code>gte</code>, <code>lt</code> and <code>lte</code>, plus <code>and</code>, <code>or</code> and <code>not</code>. Put one inside <code>&lcub;&lcub;if&rcub;&rcub;</code> to act on it.</dd>\n                <dt><code>&lcub;&lcub;switch::&lcub;&lcub;getvar::mood&rcub;&rcub;::happy=She beams.::sad=She sighs.::default=She waits.&rcub;&rcub;</code></dt>\n                <dd>Picks the text that matches the value.</dd>\n                <dt><code>&lcub;&lcub;calc::(3 + 4) - 2&rcub;&rcub;</code> <code>&lcub;&lcub;clamp::&lcub;&lcub;getvar::hp&rcub;&rcub;::0::100&rcub;&rcub;</code></dt>\n                <dd>Does the sum, or keeps a number between two limits.</dd>\n                <dt><code>&lcub;&lcub;expr::&lcub;&lcub;getvar::day&rcub;&rcub; &gt; 3&rcub;&rcub;</code></dt>\n                <dd>Writes a whole comparison in one go. The setting \'Work out comparisons in if conditions\' lets <code>&lcub;&lcub;if&rcub;&rcub;</code> do this directly.</dd>\n            </dl>\n\n            <h4 class="necoHelpHeading">Text tools</h4>\n            <dl class="necoHelpList">\n                <dt><code>&lcub;&lcub;default::&lcub;&lcub;getvar::mood&rcub;&rcub;::calm&rcub;&rcub;</code></dt>\n                <dd>Uses calm when mood is empty.</dd>\n                <dt><code>&lcub;&lcub;truncate::&lcub;&lcub;description&rcub;&rcub;::300&rcub;&rcub;</code></dt>\n                <dd>Cuts text down to 300 characters.</dd>\n                <dt><code>&lcub;&lcub;replace::the cat sat::cat::dog&rcub;&rcub;</code> <code>&lcub;&lcub;upper::hi&rcub;&rcub;</code></dt>\n                <dd>Swaps words, or changes capital letters.</dd>\n            </dl>\n\n            <h4 class="necoHelpHeading">Chat variables</h4>\n            <p>These live in the chat file and are kept separately from Taro\'s <code>&lcub;&lcub;setvar&rcub;&rcub;</code> variables.</p>\n            <dl class="necoHelpList">\n                <dt><code>&lcub;&lcub;setchatvar::location::Forest&rcub;&rcub;</code> <code>&lcub;&lcub;getchatvar::location&rcub;&rcub;</code></dt>\n                <dd>Save a value and read it back.</dd>\n                <dt><code>&lcub;&lcub;addchatvar::minutes::15&rcub;&rcub;</code></dt>\n                <dd>Adds to it.</dd>\n                <dt><code>&lcub;&lcub;foreachChatVar::stat_::s&rcub;&rcub;&lcub;&lcub;.s&rcub;&rcub;: &lcub;&lcub;.s_value&rcub;&rcub; &lcub;&lcub;/foreachChatVar&rcub;&rcub;</code></dt>\n                <dd>Repeats for every chat variable whose name starts with stat_, in alphabetical order.</dd>\n            </dl>\n\n            <h4 class="necoHelpHeading">Lorebooks and pronouns</h4>\n            <dl class="necoHelpList">\n                <dt><code>&lcub;&lcub;lore::Backstory&rcub;&rcub;</code></dt>\n                <dd>Pulls in the text of the lorebook entry called Backstory. <code>&lcub;&lcub;lore::Kingdom::My World&rcub;&rcub;</code> looks in one book. Right after a chat opens it can come back empty for a moment.</dd>\n                <dt><code>&lcub;&lcub;sub&rcub;&rcub;</code> <code>&lcub;&lcub;obj&rcub;&rcub;</code> <code>&lcub;&lcub;poss&rcub;&rcub;</code> <code>&lcub;&lcub;ref&rcub;&rcub;</code></dt>\n                <dd>Your persona\'s pronouns, like she, her, her and herself. Add char in front for the character\'s, like <code>&lcub;&lcub;charsub&rcub;&rcub;</code>. A capital letter, like <code>&lcub;&lcub;Sub&rcub;&rcub;</code>, capitalises the result.</dd>\n                <dt><code>&lcub;&lcub;pverb::is::are&rcub;&rcub;</code></dt>\n                <dd>Picks the verb that fits the pronouns. Save persona and character pronouns in Macro Enhanced\'s Setup tab, or set them for one chat with <code>&lcub;&lcub;setpronouns::he/him&rcub;&rcub;</code>. Until you do, it\'s they and them.</dd>\n            </dl>\n\n            <h4 class="necoHelpHeading">Your own macros</h4>\n            <p>Open Fine-tuning → Macro Enhanced → My macros to make one, or type it out:</p>\n            <dl class="necoHelpList">\n                <dt><code>/me-define name=greet args=who Hello &lcub;&lcub;who&rcub;&rcub;, good &lcub;&lcub;timeofday&rcub;&rcub;!</code></dt>\n                <dd>Now <code>&lcub;&lcub;greet::Alice&rcub;&rcub;</code> writes a greeting for Alice. A macro can belong to everything, one character or one chat; the narrowest one wins.</dd>\n            </dl>\n            <p class="necoHelpTip">If a macro name clashes with another extension, Macro Enhanced\'s version is still there with <code>me-</code> in front, like <code>&lcub;&lcub;me-upper::hi&rcub;&rcub;</code>. <code>/me-macros</code> lists everything it added.</p>\n\n            <h4 class="necoHelpHeading">Macro Workbench</h4>\n            <p>Fine-tuning → Macro Enhanced opens the Workbench. Try macros in Playground without touching saved variables or sending a model request. Reference has searchable help and examples; My macros holds your own macros, templates, import and export. This chat shows saved values and the cache audit. Setup holds saved pronouns and syntax switches. Nori\'s Tour walks through the page, and <code>/me-workbench</code> opens it too.</p>\n            <div class="necoHelpActions">\n                <button type="button" class="necoHelpChip necoHelpChip--primary" data-neconyan-help-action="workbench"><i class="fa-solid fa-flask" aria-hidden="true"></i><span>Open Macro Workbench</span></button>\n            </div>\n            <p class="necoHelpFine">Macro Enhanced needs to be switched on under Extensions. If it\'s off, the macros in this section won\'t work.</p>\n        </div>\n    </details>\n\n    <p class="necoHelpFooter">Rather ask? Open one of us from Choose an assistant on Home. We can get things wrong, so check anything important against this guide.</p>\n</div>\n',
    '/scripts/templates/hotkeys.html': '<div>\n    <strong data-i18n="help_hotkeys_0">Chat Hotkeys</strong>\n</div>\n<ul>\n    <li><kbd data-i18n="help_hotkeys_1">Up</kbd> = <span data-i18n="help_hotkeys_2">Edit last message in chat</span></li>\n    <li><kbd data-i18n="help_hotkeys_3">Ctrl+Up</kbd> = <span data-i18n="help_hotkeys_4">Edit last USER message in chat</span></li>\n    <li><kbd data-i18n="help_hotkeys_5">Left</kbd> = <span data-i18n="help_hotkeys_6">swipe left</span></li>\n    <li><kbd data-i18n="help_hotkeys_7">Right</kbd> = <span data-i18n="help_hotkeys_8">swipe right (NOTE: swipe hotkeys only apply without modifiers and are disabled when chatbar has something typed into it)</span></li>\n    <li><kbd data-i18n="help_hotkeys_9">Enter</kbd> <span data-i18n="help_hotkeys_10">(with chat bar selected)</span> = <span data-i18n="help_hotkeys_10_1">send your message to AI</span></li>\n    <li><kbd data-i18n="help_hotkeys_11">Ctrl+Enter</kbd> = <span data-i18n="help_hotkeys_12">Regenerate the last AI response</span></li>\n    <li><kbd data-i18n="help_hotkeys_13">Alt+Enter</kbd> = <span data-i18n="help_hotkeys_14">Continue the last AI response</span></li>\n    <li><kbd data-i18n="help_hotkeys_15">Escape</kbd> = <span data-i18n="help_hotkeys_16">stop AI response generation, close UI panels, cancel message edit</span></li>\n    <li><kbd data-i18n="help_hotkeys_17">Ctrl+Shift+Up</kbd> = <span data-i18n="help_hotkeys_18">Scroll to context line</span></li>\n    <li><kbd data-i18n="help_hotkeys_19">Ctrl+Shift+Down</kbd> = <span data-i18n="help_hotkeys_20">Scroll chat to bottom</span></li>\n</ul>\n<div>\n    <strong data-i18n="help_hotkeys_20">Markdown Hotkeys</strong>\n</div>\n<div>\n    <small>\n        <span data-i18n="help_hotkeys_21">Works in the chatbar and textareas marked with this icon:</span>\n        <code><i class="fa-brands fa-markdown"></i></code>\n    </small>\n</div>\n<ul>\n    <li><kbd>Ctrl+B</kbd> = <span data-i18n="help_hotkeys_22">**bold**</span></li>\n    <li><kbd>Ctrl+I</kbd> = <span data-i18n="help_hotkeys_23">*italic*</span></li>\n    <li><kbd>Ctrl+U</kbd> = <span data-i18n="help_hotkeys_24">__underline__</span></li>\n    <li><kbd>Ctrl+K</kbd> = <span data-i18n="help_hotkeys_25">`inline code`</span></li>\n    <li><kbd>Ctrl+Shift+~</kbd> = <span data-i18n="help_hotkeys_26">~~strikethrough~~</span></li>\n</ul>\n',
    '/scripts/templates/formatting.html': '<span data-i18n="help_format_1">Text formatting commands:</span>\n<ul> <!-- I know it seems like all these \'display as\' could fit into just a couple entries, but other languages might need it with their grammar\nActually I feel that languages with SOV might need even more extra entries, but let\'s KISS it for now, those can be easily added in the future without breaking anything -->\n    <li><tt data-i18n="help_format_2">*text*</tt> - <span data-i18n="help_format_3">displays as </span><i data-i18n="help_format_4">italics</i></li>\n    <li><tt data-i18n="help_format_5">**text**</tt> - <span data-i18n="help_format_6">displays as </span><b data-i18n="help_format_7">bold</b></li>\n    <li><tt data-i18n="help_format_8">***text***</tt> - <span data-i18n="help_format_9">displays as </span><b><i data-i18n="help_format_10">bold italics</i></b></li>\n    <li><tt data-i18n="help_format_11">__text__</tt> - <span data-i18n="help_format_12">displays as an </span><u data-i18n="help_format_13">underline</u></li>\n    <li><tt data-i18n="help_format_14">~~text~~</tt> - <span data-i18n="help_format_15">displays as a </span><del data-i18n="help_format_16">strikethough</del></li>\n    <li><tt data-i18n="help_format_17">[text](url)</tt> - <span data-i18n="help_format_18">displays as a </span><a href="#" data-i18n="help_format_19">hyperlink</a></li>\n    <li><tt data-i18n="help_format_20">![text](url)</tt> - <span data-i18n="help_format_21">displays as an image</span></li>\n    <li><tt data-i18n="help_format_22">```text```</tt> - <span data-i18n="help_format_23">displays as a code block (new lines allowed between the backticks)</span></li>\n</ul>\n<pre><code data-i18n="help_format_like_this"> like this</code></pre>\n<ul>\n    <li><tt data-i18n="help_format_24">`text`</tt> - <span data-i18n="help_format_25">displays as </span><code data-i18n="help_format_26">inline code</code></li>\n    <li><tt data-i18n="help_format_27">&gt; text</tt> - <span data-i18n="help_format_28">displays as a blockquote (note the space after &gt;)</span></li>\n    <blockquote data-i18n="help_format_like_this">like this</blockquote>\n    <li><tt data-i18n="help_format_29"># text</tt> - <span data-i18n="help_format_30">displays as a large header (note the space)</span></li>\n    <h1 data-i18n="help_format_like_this">like this</h1>\n    <li><tt data-i18n="help_format_32">## text</tt> - <span data-i18n="help_format_33">displays as a medium header (note the space)</span></li>\n    <h2 data-i18n="help_format_like_this">like this</h2>\n    <li><tt data-i18n="help_format_35">### text</tt> - <span data-i18n="help_format_36">displays as a small header (note the space)</span></li>\n    <h3 data-i18n="help_format_like_this">like this</h3>\n</ul>\n',
    '/scripts/templates/welcome.html': '<div class="welcomeGuidePanel">\n    <div class="welcomeGuideHeader">\n        <div class="welcomeHeroEyebrow">Workspace help</div>\n        <h3>\n            <span id="version_display_welcome">{{displayVersion}}</span>\n        </h3>\n        <p>Choose a character on Home, or start a temporary chat.</p>\n    </div>\n\n    <div class="welcomeGuideLinks">\n        <a target="_blank" rel="noopener noreferrer" href="https://platberlitz.github.io/neconyan-docs/">Official Neconyan handbook</a>\n        <span><code>/?</code> opens command help inside the chat bar.</span>\n    </div>\n</div>\n',
    '/scripts/templates/welcomePrompt.html': '<!-- Welcome prompt intentionally removed in the Neconyan shell redesign. -->\n',
    '/scripts/templates/assistantNote.html': '<div data-type="assistant_note">\n    <div class="assistant_note_title">\n        <b data-i18n="Note:">Note:</b> <span data-i18n="this chat is temporary and will be deleted as soon as you leave it.">this chat is temporary and will be deleted as soon as you leave it.</span>\n    </div>\n    <button class="assistant_note_import menu_button menu_button_icon margin0" data-i18n="[title]Import from JSONL" title="Import from JSONL">\n        <i class="fa-solid fa-file-import"></i>\n        <span data-i18n="Load">Load</span>\n    </button>\n    <button class="assistant_note_export menu_button menu_button_icon margin0" data-i18n="[title]Export as JSONL" title="Export as JSONL">\n        <i class="fa-solid fa-file-export"></i>\n        <span data-i18n="Save">Save</span>\n    </button>\n</div>\n',
    '/scripts/templates/welcomePanelOnboarding.html': '<div class="welcomePanel neconyan-home {{#if welcomePanelCompact}}welcomePanel--compact{{/if}}{{#if welcomePanelListOnly}} welcomePanel--listOnly{{/if}}" data-home-panel-mode="{{welcomePanelMode}}">\n    <section class="neconyan-home-intro welcomeHero neconyan-cat-panel" aria-labelledby="welcome-home-title">\n        <div class="neconyan-home-cat">\n            <img src="img/neconyan-pixel-cat.webp?v=20260913g" alt="A calico cat blinking, flicking its tail, and tumbling" width="208" height="192" data-neconyan-cat>\n            <button type="button" class="neconyan-cat-toggle" data-neconyan-cat-toggle>Pause cat animation</button>\n        </div>\n        <h1 id="welcome-home-title">Meowlcome to Neconyan~</h1>\n        <p>Find your purrfect chat pal~! Start with a character already included, or start a temporary chat!</p>\n        <div class="neconyan-home-actions">\n            {{#if hasActiveChat}}\n            <button type="button" class="menu_button welcomeActionButton neconyan-home-primary" data-action="resume-chat"><i class="fa-solid fa-comment" aria-hidden="true"></i><span>Continue your chat</span><i class="fa-solid fa-arrow-right" aria-hidden="true"></i></button>\n            {{/if}}\n            <button type="button" class="menu_button welcomeActionButton {{#unless hasActiveChat}}neconyan-home-primary{{/unless}}" data-action="open-characters-menu"><i class="fa-solid fa-address-card" aria-hidden="true"></i><span>Choose a character</span><i class="fa-solid fa-arrow-right" aria-hidden="true"></i></button>\n            <button type="button" class="menu_button openTemporaryChat"><i class="fa-solid fa-pen" aria-hidden="true"></i><span>Start a temporary chat<small>Messages are not saved.</small></span><i class="fa-solid fa-arrow-right" aria-hidden="true"></i></button>\n            <button type="button" class="menu_button welcomeActionButton" data-action="open-tab" data-action-value="left:api"><i class="fa-solid fa-plug" aria-hidden="true"></i><span>Connect a model</span><i class="fa-solid fa-arrow-right" aria-hidden="true"></i></button>\n        </div>\n    </section>\n    <section class="neconyan-home-layout-bar" aria-labelledby="neconyan-home-layout-title">\n        <h2 id="neconyan-home-layout-title"><i class="fa-solid fa-table-columns" aria-hidden="true"></i>Home layout</h2>\n        <div class="neconyan-home-layout" role="group" aria-labelledby="neconyan-home-layout-title"><button type="button" class="menu_button" data-welcome-panel-mode-target="full">Full home</button><button type="button" class="menu_button" data-welcome-panel-mode-target="compact">Compact</button><button type="button" class="menu_button" data-welcome-panel-mode-target="list">Recent chats only</button><button type="button" class="menu_button welcomeActionButton" data-action="replay-tutorial">Replay First paws tour</button></div>\n    </section>\n    {{#if assistantPersonalities}}\n    <section class="neconyan-assistant-picker neconyan-cat-panel{{#if assistantsCollapsed}} is-collapsed{{/if}}" data-assistant-picker aria-labelledby="neconyan-assistant-picker-title">\n        <div class="neconyan-assistant-picker-heading">\n            <div><h2 id="neconyan-assistant-picker-title">Choose an assistant</h2><p>Miso the tiger and Taro and Nori the cats! They know all about Neconyan, so don\'t be afraid to ask them anything. Do be mindful of hallucinations, though; double check everything!</p></div>\n            <button type="button" class="menu_button welcomeActionButton neconyan-assistant-collapse" data-action="collapse-assistants" aria-expanded="{{#if assistantsCollapsed}}false{{else}}true{{/if}}" aria-controls="neconyan-assistant-choices"><i class="fa-solid {{#if assistantsCollapsed}}fa-chevron-down{{else}}fa-chevron-up{{/if}}" aria-hidden="true"></i><span>{{#if assistantsCollapsed}}Expand{{else}}Collapse{{/if}}</span></button>\n        </div>\n        <button type="button" class="menu_button welcomeActionButton neconyan-assistant-disclosure" data-action="toggle-assistants" aria-expanded="false" aria-controls="neconyan-assistant-choices">Show assistants</button>\n        <div id="neconyan-assistant-choices" class="neconyan-assistant-choices">\n            <div class="neconyan-assistant-list">\n                {{#each assistantPersonalities}}\n                <article class="neconyan-assistant-row" data-assistant-name="{{name}}" data-assistant-personality="{{id}}">\n                    <div class="neconyan-assistant-portrait-wrap"><img src="{{initialPortrait}}" alt="{{name}} assistant portrait" width="112" height="152" loading="lazy" decoding="async" data-assistant-portrait></div>\n                    <div class="neconyan-assistant-copy"><h3>{{name}}</h3><p class="neconyan-assistant-role">{{role}}</p><p>{{summary}}</p><p class="neconyan-assistant-selection" data-assistant-selection aria-live="polite">Choose Male, Female or Neutral.</p></div>\n                    <fieldset class="neconyan-assistant-variants"><legend>{{genderLegend}}</legend>\n                        {{#each variants}}<label for="neconyan-assistant-{{id}}"><input id="neconyan-assistant-{{id}}" type="radio" name="assistant-{{../id}}" value="{{id}}" data-assistant-variant data-gender="{{gender}}" data-portrait="{{portrait}}"{{#if selected}} checked{{/if}}><span>{{label}}</span></label>{{#if updateAvailable}}<button type="button" class="menu_button neconyan-assistant-update" data-assistant-update data-assistant-id="{{id}}" data-assistant-label="{{../name}} ({{label}})" data-assistant-update-avatar="{{installedAvatar}}" aria-label="Install updated {{../name}} ({{label}}) copy">Install updated copy</button>{{/if}}{{/each}}\n                    </fieldset>\n                    <button type="button" class="menu_button neconyan-assistant-open" data-assistant-open disabled><span data-assistant-action-label>Choose a gender</span><i class="fa-solid fa-arrow-right" aria-hidden="true"></i></button>\n                </article>\n                {{/each}}\n            </div>\n            <p class="neconyan-assistant-picker-status" data-assistant-picker-status role="status" aria-live="polite">Choose a gender to open an assistant.</p>\n        </div>\n    </section>\n    {{else}}\n    <section class="neconyan-assistant-picker neconyan-assistant-picker--error neconyan-cat-panel" data-assistant-picker aria-labelledby="neconyan-assistant-picker-title">\n        <img class="neconyan-empty-illustration" src="img/neconyan/curious-search.webp" alt="" width="536" height="510" aria-hidden="true" loading="lazy" decoding="async">\n        <div><p class="neconyan-eyebrow">Assistant library</p><h2 id="neconyan-assistant-picker-title">The assistant catalog is unavailable</h2><p>You can still choose a character or start a temporary chat.</p></div>\n        <button type="button" class="menu_button" data-assistant-catalog-retry>Try again</button>\n        <p class="neconyan-assistant-picker-status" data-assistant-picker-status role="status" aria-live="polite"></p>\n    </section>\n    {{/if}}\n    <section class="welcomeRecentShell neconyan-cat-panel" aria-labelledby="welcome-recent-title">\n        <div class="neconyan-recent-heading">\n            <h2 id="welcome-recent-title">Recent chats</h2>\n            <details class="neconyan-recent-filters">\n                <summary>Filter chats</summary>\n                <div class="welcomeRecentTabs" role="group" aria-label="Chat types">\n                    <button type="button" class="welcomeRecentTab active" data-recent-chat-filter="all" aria-pressed="true">All chats</button>\n                    <button type="button" class="welcomeRecentTab" data-recent-chat-filter="individual" aria-pressed="false">Character chats</button>\n                    <button type="button" class="welcomeRecentTab" data-recent-chat-filter="group" aria-pressed="false">Group chats</button>\n                    <button type="button" class="welcomeRecentTab" data-recent-chat-filter="conversation" aria-pressed="false">Direct chats</button>\n                    <button type="button" class="welcomeRecentTab {{#unless separateAgentRecentChats}}displayNone{{/unless}}" data-recent-chat-filter="agent" aria-pressed="false">Agent chats</button>\n                </div>\n            </details>\n            <button type="button" class="menu_button welcomeActionButton neconyan-recent-archive" data-action="open-chat-archive"><i class="fa-solid fa-box-archive" aria-hidden="true"></i><span>Chat Archive</span></button>\n        </div>\n        <div class="welcomeRecent">\n            <div id="welcome-recent-chat-list" class="recentChatList">\n                {{#if empty}}<div class="noRecentChat"><img class="neconyan-empty-illustration" src="img/neconyan/sleepy-chat.webp" alt="" width="536" height="436" aria-hidden="true" loading="lazy" decoding="async"><strong>Your chats will appear here.</strong><span>Mew beginnings start with a chat. Choose a character above, then find your saved chats here.</span></div>{{/if}}\n                <div class="noRecentChat displayNone" data-recent-chat-empty-state="filtered"><strong>No chats match this filter.</strong><span>Choose another chat type.</span></div>\n                {{#each chats}}{{#with this}}\n                <article class="recentChat {{#if hidden}}hidden{{/if}} {{#if is_group}}group{{else}}individual{{/if}} {{#if is_agent}}agent{{/if}} {{#if is_conversation}}conversation{{/if}}" data-recent-chat-type="{{recent_chat_type}}" data-file="{{chat_name}}" data-avatar="{{avatar}}" data-group="{{group}}" data-conversation-branch-id="{{conversation_branch_id}}" data-conversation-branch-name="{{conversation_branch_name}}">\n                    <button type="button" class="recentChatOpen"><span class="sr-only">Open {{char_name}}: {{chat_name}}</span></button>\n                    {{#if pinned}}<div class="recentChatPinned"><i class="fa-solid fa-thumbtack" title="Pinned chat" aria-label="Pinned chat"></i></div>{{/if}}\n                    <div class="avatar"><img src="{{char_thumbnail}}" alt="{{char_name}}" width="48" height="48" loading="lazy" decoding="async"></div>\n                    <div class="recentChatInfo">\n                        <div class="chatNameContainer">\n                            <div class="chatName"><strong class="characterName">{{char_name}}</strong><span>{{chat_name}}</span></div>\n                            <small class="chatDate" title="{{date_long}}">{{date_short}}</small>\n                        </div>\n                        <div class="chatMessageContainer"><div class="chatMessage">{{mes}}</div></div>\n                        <div class="chatActions">\n                            <button type="button" class="menu_button pinChat {{#if pinned}}active{{/if}}" aria-label="{{#if pinned}}Unpin chat{{else}}Pin chat{{/if}}" aria-pressed="{{#if pinned}}true{{else}}false{{/if}}"><i class="fa-solid fa-thumbtack" aria-hidden="true"></i><span>{{#if pinned}}Unpin{{else}}Pin{{/if}}</span></button>\n                            <button type="button" class="menu_button renameChat" aria-label="Rename chat"><i class="fa-solid fa-pen" aria-hidden="true"></i><span>Rename</span></button>\n                            <button type="button" class="menu_button deleteChat" aria-label="Delete chat"><i class="fa-solid fa-trash" aria-hidden="true"></i><span>Delete</span></button>\n                        </div>\n                    </div>\n                </article>\n                {{/with}}{{/each}}\n                {{#if more}}<button type="button" class="menu_button showMoreChats" aria-controls="welcome-recent-chat-list" aria-expanded="false">Show more chats</button>{{/if}}\n            </div>\n        </div>\n    </section>\n    <div class="neconyan-home-footer welcomePanelPersistentControls">\n        <button type="button" class="menu_button welcomeActionButton" data-action="open-global-search"><i class="fa-solid fa-magnifying-glass" aria-hidden="true"></i><span>Find a setting</span></button>\n    </div>\n</div>\n',
};
